//! Complete source-neutral ownership-form DATA; only the private host owns EOF.
use std::{sync::Arc,io,collections::BTreeMap};
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,reactive_raw_policy_pages::RawPolicyPages,key_policy_control::{self as kc,Control},sys_ownership_forms_policy as policy,lint::{Site,AllowUse}};
pub fn metadata()->&'static crate::lint::Meta{static META:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();META.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:"dx_ownership_forms",rules:policy::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
fn oom(b:&Budget,m:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(p:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&p,Err(Failure::Operational(_))){return p}checked(b,poll)?;p}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn row<C:Control,T>(c:&mut C,v:&mut Vec<T>)->Result<(),C::Error>{if v.len()<v.capacity(){return Ok(())}let cap=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let max=cap.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||max.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;v.try_reserve_exact(cap-v.len()).map_err(|_|c.allocation_failed())?;if v.capacity()>max{return Err(c.allocation_failed())}Ok(())}
struct Hit{rule:&'static str,relative:String,line:u32,value:Option<Resolved>}
enum Resolved{Site(Site,String),Allow(AllowUse)}
pub struct OwnershipFormsData{sites:Vec<Site>,source_text:Vec<String>,allow_used:Vec<AllowUse>,allow_digests:BTreeMap<String,[u8;20]>}
impl OwnershipFormsData{pub fn metadata(&self)->&'static crate::lint::Meta{metadata()}pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn allow_digests(&self)->&BTreeMap<String,[u8;20]>{&self.allow_digests}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allow_used.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for s in &self.sites{for text in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(text.capacity())?;}}for text in &self.source_text{n=n.checked_add(text.capacity())?;}for a in &self.allow_used{for text in [&a.rel,&a.name,&a.code]{n=n.checked_add(text.capacity())?;}}for label in self.allow_digests.keys(){n=n.checked_add(2048+std::mem::size_of::<(String,[u8;20])>())?.checked_add(label.capacity())?;}Some(n)}}
pub fn collect(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<OwnershipFormsData,Failure>{collect_using(pages,root,poll,None)}
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<OwnershipFormsData,Failure>{collect_using(pages,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<OwnershipFormsData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=PatternOperation{patterns,budget:keep,poll};let mut files=Vec::new();if !pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let p=(||{let file=views.source_file()?;let mut temporary=PatternOperation{patterns,budget:local,poll};let facts=policy::facts_using(file,&mut work,&mut temporary)?;row(&mut work,&mut files)?;files.push((kc::own(&mut work,relative)?,facts));Ok(true)})();finish(p,local,poll)})?{return Err("ownership-form facts source omitted actual selected EOF".into())}
let mut hits=Vec::new();let borrowed:Vec<_>={kc::reserve(&mut work,||files.len().checked_mul(4*std::mem::size_of::<(&str,&policy::Facts)>())?.checked_add(128))?;let rows:Vec<_>=files.iter().map(|(rel,facts)|(rel.as_str(),facts)).collect();if rows.capacity()>files.len().saturating_mul(4){return Err(work.allocation_failed())}rows};policy::scan_borrowed_using(&borrowed,&mut work,&mut|rule,relative,line,c|{row(c,&mut hits)?;hits.push(Hit{rule,relative:kc::own(c,relative)?,line,value:None});Ok(())})?;drop(borrowed);
let mut requests=Vec::new();for index in 0..hits.len(){work.checkpoint()?;row(&mut work,&mut requests)?;requests.push(index);}kc::reserve(&mut work,||requests.len().checked_mul(std::mem::size_of::<usize>())?.checked_add(128))?;requests.sort_by(|a,b|{let a=&hits[*a];let b=&hits[*b];(a.relative.as_str(),a.line).cmp(&(b.relative.as_str(),b.line))});let mut digests=BTreeMap::new();if !pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let p=(||{let file=views.source_file()?;let mut temporary=PatternOperation{patterns,budget:local,poll};let low=requests.partition_point(|i|hits[*i].relative.as_str()<relative);let high=requests.partition_point(|i|hits[*i].relative.as_str()<=relative);let mut allowed=false;for index in &requests[low..high]{temporary.checkpoint()?;let hit=&mut hits[*index];if hit.value.is_some(){return Err("ownership-form source row was repeated".into())}let name=kc::format(&mut temporary,format_args!("sys_{}",hit.rule))?;hit.value=Some(if let Some(kept)=crate::allow::kept_using(file,hit.line as usize,&name,&mut temporary)?{let code=kept.code.unwrap_or_default();work.reserve(code.capacity())?;allowed=true;Resolved::Allow(AllowUse{rel:kc::own(&mut work,relative)?,line:u32::try_from(kept.line).map_err(|_|work.overflow())?,name:kc::own(&mut work,&name)?,code})}else{let raw=file.raw();let original=raw.line(hit.line as usize);let words=original.split_whitespace().try_fold(0usize,|n,_|{temporary.checkpoint()?;n.checked_add(1).ok_or_else(||temporary.overflow())})?;kc::reserve(&mut temporary,||words.checked_mul(4*std::mem::size_of::<&str>())?.checked_add(original.len().checked_mul(4)?)?.checked_add(256))?;let text=crate::util::normalize_ws(original);work.reserve(text.capacity())?;Resolved::Site(Site{rule:kc::own(&mut work,hit.rule)?,rel:kc::own(&mut work,relative)?,line:hit.line,msg:String::new(),key:String::new(),ident:String::new()},text)});}if allowed{kc::reserve(&mut work,||Some(2048+std::mem::size_of::<(String,[u8;20])>()))?;digests.insert(kc::own(&mut work,relative)?,crate::captured_raw_file::source_allow_digest(file));}Ok(true)})();finish(p,local,poll)})?{return Err("ownership-form ALLOW/source-line phase omitted actual selected EOF".into())}
let mut output=OwnershipFormsData{sites:Vec::new(),source_text:Vec::new(),allow_used:Vec::new(),allow_digests:digests};for hit in hits{work.checkpoint()?;match hit.value.ok_or("ownership-form finding lacks actual selected original row")?{Resolved::Site(site,text)=>{row(&mut work,&mut output.sites)?;row(&mut work,&mut output.source_text)?;output.sites.push(site);output.source_text.push(text);},Resolved::Allow(value)=>{if !output.allow_used.contains(&value){row(&mut work,&mut output.allow_used)?;output.allow_used.push(value);}}}}checked(keep,poll)?;Ok(output)})();let p=finish(pending,keep,poll);let p=match p{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"ownership-form output capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(e)=>{drop(data);Err(e)}}},Err(e)=>Err(e)};phase.ok=p.is_ok();drop(phase);finish(p,root,poll)}
